interface OrderObserver {
    void update(Order order);
}
class Order {
    private List<OrderObserver> observers = new ArrayList<>();
    private String status;
    void attach(OrderObserver o) { observers.add(o); }
    void detach(OrderObserver o) { observers.remove(o); }
    String getStatus() { return status; }
    void setStatus(String s) {
        status = s;
        for (OrderObserver o : observers) o.update(this);
    }
}
class StockModule implements OrderObserver {
    public void update(Order order) { /* 按订单状态调整库存 */ }
}
class SmsModule implements OrderObserver {
    public void update(Order order) { /* 给顾客发送状态短信 */ }
}
// 使用：order.attach(new StockModule()); order.attach(new SmsModule());
